CREATE TABLE IF NOT EXISTS mm_conversations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), listing_id UUID NOT NULL REFERENCES mm_listings(id) ON DELETE CASCADE, requester_id TEXT NOT NULL, publisher_id TEXT NOT NULL, blocked_by TEXT DEFAULT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (listing_id, requester_id), CHECK (requester_id <> publisher_id))